            . '<div class="wrap"><header class="masthead" data-level="Beginner"><div class="course-cover"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 360" preserveAspectRatio="xMidYMid slice" role="img" aria-label="A garden"><rect width="640" height="360" fill="#2f7d5b"/><circle cx="320" cy="180" r="90" fill="#d7b24a"/></svg></div><span class="eyebrow">Short course &middot; The garden</span><h1>Growing <em>Vegetables</em></h1><p class="course-subtitle">From seed to supper</p><p class="course-summary">A practical course on growing food at home.</p><div class="meta"><span><b>2</b> modules</span><span>Graded self-tests</span></div></header>'
