            . '<div class="modules">' . self::module(1, 'Soil and compost', 'What grows well, and why', $answerKeys, false) . self::module(2, 'Sowing and planting', 'When each crop goes in', $answerKeys, true) . '</div>'
            . '<section class="final acc-item" id="final"><button class="acc-trigger" aria-expanded="false"><span class="node"><span class="num">F</span></span><span class="m-titles"><span class="eyebrow">Assessment</span><span class="m-name">The Gardener\'s Examination</span><small>Drawn from both modules.</small></span><span class="chev">&#8250;</span></button>'
