            . '<div class="overall" id="overallPanel"><div id="ovLabel"></div></div></div><script>' . self::script($answerKeys) . '</script></body></html>';
    }

    private static function module(int $number, string $title, string $subtitle, bool $answerKeys, bool $practical): string
    {
        $key = 'm' . $number;
        $panel = static fn(string $kind, string $icon, string $label, string $line, string $inner): string => '<section class="sub ' . $kind . ' acc-item"><button class="acc-trigger" aria-expanded="false"><span class="sub-ico">' . $icon . '</span><span class="sub-label">' . $label . '<small>' . $line . '</small></span><span class="chev">&#8250;</span></button><div class="acc-panel"><div class="acc-inner"><div class="sub-inner">' . $inner . '</div></div></div></section>';
        return '<section class="module acc-item" id="mod-' . $key . '" data-assessment-required="true"><button class="acc-trigger module-trigger" aria-expanded="false"><span class="node"><span class="num">0' . $number . '</span></span><span class="m-titles"><span class="eyebrow">Module 0' . $number . '</span><span class="m-name">' . $title . '</span><small>' . $subtitle . '</small></span><span class="m-grade" data-grade=""></span><span class="chev">&#8250;</span></button>'
            . '<div class="acc-panel"><div class="acc-inner"><div class="module-inner"><div class="module-body"><div class="outcomes"><span class="eyebrow">Learning outcomes</span><ol><li>Explain ' . strtolower($title) . '.</li></ol></div><h4>' . $title . '</h4><p>Everything starts below the surface, so test your soil with a jar before you plant anything in module ' . $number . '.</p>'
            . '<div class="video"><iframe src="https://www.youtube-nocookie.com/embed/dQw4w9WgXcQ" title="A garden tour" allowfullscreen></iframe><p class="video-cap"><b>Video introduction.</b> A garden tour, about 3 minutes. Open it on YouTube if the player does not load.</p></div>'
            // Some originals put a practical straight in the module's body, with no box round it.
            . ($practical ? '<details class="block practical"><summary class="block-head"><span class="sub-ico">&#9998;</span><span class="sub-label">Practical work</span></summary><div class="block-inner sub-inner"><section class="task"><h4>Task 1: Sow a row</h4><p>Sow one row of radishes and write down the date.</p></section></div></details><details class="block answers"><summary class="block-head"><span class="sub-ico">&#10003;</span><span class="sub-label">Model answers</span></summary><div class="block-inner sub-inner"><section class="answer"><h4>Task 1: Sow a row</h4><p>A straight row, a finger deep, watered in.</p></section></div></details>' : '')
            . '<div class="subs">' . $panel('s-summary', '&#9733;', 'Summary', 'The key points in brief', '<ul><li>Feed the soil and the soil feeds the plant in module ' . $number . '.</li></ul>')
            . $panel('s-assess', '&#10003;', 'Self Assessment', 'One question, graded at once', '<div class="quiz" data-quiz="' . $key . '"></div>')
            . ($answerKeys ? $panel('s-answers', '&#9998;', 'Answer Key', 'The correct option for this module', '<p class="answer-note">The correct option and a short explanation for each question.</p><ol class="key-list" data-key="' . $key . '"></ol>') : '')
            . '</div></div></div></div></div></section>';
    }

    private static function css(): string
    {
        return ':root{--ink:#14342b;--paper:#f3f6ef;--green:#1f6b4f}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"IBM Plex Sans",Arial,sans-serif;font-size:17px}'
            . '.wrap{max-width:900px;margin:0 auto;padding:20px}.masthead{background:var(--ink);color:#fff;padding:28px;border-radius:14px}.masthead h1{font-family:Spectral,Georgia,serif;font-size:44px;margin:.2rem 0}.masthead h1 em{color:#d7b24a}.meta span{border:1px solid #fff;border-radius:99px;padding:2px 10px;margin-right:6px}'
            . '.progress-strip{background:#fff;padding:10px}.ps-fill{height:6px;background:var(--green);width:0}.cards{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:14px 0}.info{background:#fff;padding:14px;border-radius:10px}'
            . '.acc-trigger{width:100%;border:0;background:transparent;text-align:left;font:inherit;color:inherit;cursor:pointer;display:flex;align-items:center;gap:.75rem}.acc-panel{display:none}.acc-item.open>.acc-panel{display:block}.acc-item.open>.acc-trigger .chev{transform:rotate(90deg)}'
            . '.module,.final{background:#fff;border-radius:12px;margin:12px 0}.module>.acc-trigger,.final>.acc-trigger{padding:18px}.module.open{box-shadow:0 8px 24px rgba(0,0,0,.12)}.module.done .node{background:var(--green);color:#fff}.node{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;border:2px solid var(--green)}'
            . '.m-titles{flex:1}.m-name{display:block;font-family:Spectral,Georgia,serif;font-size:1.25rem}.module-body{padding:0 18px 18px}.sub{border:1px solid #ddd;border-radius:10px;margin:10px 0}.sub>.acc-trigger{padding:12px;font-weight:600}.sub-inner{padding:0 14px 14px}.sub-ico{width:30px;height:30px;display:grid;place-items:center;background:#eef3e8;border-radius:8px}.sub-label small{display:block;font-weight:400}'
            . '.btn-grade{background:var(--green);color:#fff;border:0;border-radius:8px;padding:8px 16px}.overall{display:none}.overall.show{display:block}';
    }

    private static function script(bool $answerKeys): string
    {
        $script = 'const QUIZ = ' . json_encode([
            'm1' => [['q' => 'What does a jar test show?', 'o' => ['The layers of your soil', 'The price of seed'], 'a' => 0, 'e' => 'Soil settles in layers.']],
            'm2' => [['q' => 'When do most crops go in?', 'o' => ['In the depth of winter', 'After the last frost'], 'a' => 1, 'e' => 'Frost kills seedlings.']],
            'final' => [['q' => 'What should you feed?', 'o' => ['The soil', 'The fence'], 'a' => 0, 'e' => 'Feed the soil, and the soil feeds the plant.']],
        ], JSON_THROW_ON_ERROR) . ";\n" . <<<'JS'
const ALL_IDS = ["m1","m2","final"];
const state = {};
function renderQuiz(id){
  const host = document.querySelector('.quiz[data-quiz="'+id+'"]');
  if(!host) return;
  host.innerHTML = QUIZ[id].map(function(item,qi){
    return '<fieldset class="q"><legend>'+item.q+'</legend>'+item.o.map(function(o,oi){ return '<label class="opt"><input type="radio" name="'+id+'_q'+qi+'" value="'+oi+'">'+o+'</label>'; }).join('')+'</fieldset>';
  }).join('') + '<button class="btn-grade" type="button" data-grade-btn="'+id+'">Mark this module</button><span class="quiz-result"></span>';
}
function renderKey(id){
  const host = document.querySelector('.key-list[data-key="'+id+'"]');
  if(host) host.innerHTML = QUIZ[id].map(function(item){ return '<li>'+item.q+' Answer: '+item.o[item.a]+'</li>'; }).join('');
}
function updateProgress(){
  const done = ALL_IDS.filter(function(id){ return state[id]; }).length;
  const pct = Math.round(done/ALL_IDS.length*100);
  document.getElementById('psFill').style.width = pct+'%';
  document.getElementById('psPct').textContent = pct+'%';
  document.getElementById('psCount').textContent = done+' of '+ALL_IDS.length;
}
function gradeQuiz(id){
  let right = 0;
  QUIZ[id].forEach(function(item,qi){ const c = document.querySelector('input[name="'+id+'_q'+qi+'"]:checked'); if(c && parseInt(c.value,10) === item.a) right++; });
  const pct = Math.round(right/QUIZ[id].length*100);
  state[id] = pct;
  const mod = document.getElementById('mod-'+id);
  if(mod && pct < 101){ mod.classList.add('done'); mod.querySelector('[data-grade]').textContent = pct+'%'; }
  document.querySelector('.quiz[data-quiz="'+id+'"] .quiz-result').textContent = 'Score: '+pct+'%';
  if(id === 'final'){ document.getElementById('overallPanel').classList.add('show'); document.getElementById('ovLabel').textContent = 'Overall: '+pct+'%'; }
  updateProgress();
}
document.addEventListener('DOMContentLoaded', function(){
  document.querySelectorAll('.acc-trigger').forEach(function(btn){
    const item = btn.closest('.acc-item');
    btn.addEventListener('click', function(){ const open = item.classList.toggle('open'); btn.setAttribute('aria-expanded', open ? 'true' : 'false'); });
  });
  ALL_IDS.forEach(function(id){ renderQuiz(id); if(id !== 'final') renderKey(id); });
  document.body.addEventListener('click', function(e){ const g = e.target.closest('[data-grade-btn]'); if(g) gradeQuiz(g.getAttribute('data-grade-btn')); });
  document.getElementById('resetBtn').addEventListener('click', function(){ ALL_IDS.forEach(function(id){ delete state[id]; const m = document.getElementById('mod-'+id); if(m){ m.classList.remove('done'); m.querySelector('[data-grade]').textContent=''; } }); updateProgress(); });
  updateProgress();
});
JS;
        return $answerKeys ? $script : str_replace(["function renderKey(id){\n  const host = document.querySelector('.key-list[data-key=\"'+id+'\"]');\n  if(host) host.innerHTML = QUIZ[id].map(function(item){ return '<li>'+item.q+' Answer: '+item.o[item.a]+'</li>'; }).join('');\n}\n", " if(id !== 'final') renderKey(id);"], '', $script);
    }
}
